"use client"

import { usePathname, useRouter, useSearchParams } from "next/navigation"
import { useCallback, useEffect, useMemo, useRef, useState, type ReactNode } from "react"
import { ArrowUpDown, Download, MoreHorizontal, ShieldAlert, ShieldCheck } from "lucide-react"
import { toast } from "sonner"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { DetailPane, DETAIL_PANE_ID } from "@/components/queue/detail-pane"
import { FacetFilters, type Facet } from "@/components/queue/facet-filters"
import { OverrideModeProvider, useOverrideMode } from "@/components/queue/override-mode-context"
import { confirmLeave } from "@/lib/client/unsaved-changes"

export type QueueColumn<T> = {
  key: string
  label: string
  /** Kept in the narrowed list while the Detail pane is open (#225 §3). */
  narrow?: boolean
  /** Cell classes — alignment, tabular numerals, width hints. */
  className?: string
  render: (row: T) => ReactNode
}

export type SortOption<T> = { key: string; label: string; compare: (a: T, b: T) => number }

export type BulkContext = { selectedIds: string[]; clear: () => void }
export type PaneHelpers = { close: () => void; refresh: () => void }

/** The Queue screen (#225; CONTEXT.md "Queue screen"): the shared composition every typed
 * destination renders on. Two header layers — row 1 is title · Views · Sort · summary filter
 * chips · inline stat · overflow menu; row 2 is the table head — then the queue at full width
 * with its own horizontal scroller, and the one right-hand Detail pane beside it.
 *
 * Each surface (InvoiceQueue, ReceiptQueue, …) supplies its rows, columns, facets and actions;
 * this component owns selection, the pane's open/closed state, ↑/↓/Escape, deep links and the
 * checkbox set the bulk bar reads. The checkbox is bulk selection only — a row *opens* by click
 * or Enter on its title, never by checking it. */
export function QueueScreen<T>(props: QueueScreenProps<T>) {
  return <OverrideModeProvider><QueueScreenInner {...props} /></OverrideModeProvider>
}

export type QueueScreenProps<T> = {
  title: string
  /** The route this queue lives at; a selected row is reflected as `${basePath}/${id}`. */
  basePath: string
  rows: T[]
  rowId: (row: T) => string
  /** The document a row's Detail pane shows. Defaults to `rowId` — Exceptions differ, since a
   * row there is one escalated check, not one document. */
  detailIdFor?: (row: T) => string
  rowTitle: (row: T) => string
  rowSubtitle?: (row: T) => string | null
  /** The processing-state mark at the row's leading edge (CONTEXT.md "Processing state"). */
  leading?: (row: T) => ReactNode
  columns: QueueColumn<T>[]
  /** Renders the bulk-selection checkbox column. Off for surfaces with no bulk actions. */
  selectable?: boolean
  sortOptions?: SortOption<T>[]
  facets?: Facet[]
  views?: ReactNode
  /** One inline figure at the right end of row 1 (#186's metric; #205's band is gone). */
  stat?: ReactNode
  /** Additional overflow-menu items, rendered after Override Mode and Export. */
  menu?: ReactNode
  onExportAll?: () => Promise<void>
  /** The bulk action bar's contents — the surface's own buttons and dialogs. */
  bulkActions?: (context: BulkContext) => ReactNode
  empty: { title: string; body: string; filteredTitle?: string; filteredBody?: string }
  loadDetail: (documentId: string) => Promise<ReactNode | null>
  paneActions?: (row: T, helpers: PaneHelpers) => ReactNode
  paneMenu?: (row: T, helpers: PaneHelpers) => ReactNode
  /** A deep link (`/invoices/<id>`) opens the queue with that row selected and the pane open. */
  initialSelectedId?: string | null
  /** The URL search param the sort is read from and written to. Defaults to `sort`. */
  sortParam?: string
}

const INTERACTIVE = "a, button, input, select, textarea, label, [role=button], [contenteditable=true]"

function QueueScreenInner<T>({
  title, basePath, rows, rowId, detailIdFor, rowTitle, rowSubtitle, leading, columns, selectable = false, sortOptions = [], facets = [],
  views, stat, menu, onExportAll, bulkActions, empty, loadDetail, paneActions, paneMenu, initialSelectedId = null, sortParam = "sort",
}: QueueScreenProps<T>) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const overrideMode = useOverrideMode()
  const [checked, setChecked] = useState<Set<string>>(new Set())
  const [openId, setOpenId] = useState<string | null>(initialSelectedId)
  const [reloadKey, setReloadKey] = useState(0)
  const [menuOpen, setMenuOpen] = useState(false)
  const [exporting, setExporting] = useState(false)
  const rootRef = useRef<HTMLDivElement>(null)
  const triggerRefs = useRef<Map<string, HTMLButtonElement>>(new Map())

  const sortKey = searchParams.get(sortParam)
  const activeSort = sortOptions.find((option) => option.key === sortKey) ?? sortOptions[0] ?? null
  const sortedRows = useMemo(() => {
    if (!activeSort) return rows
    return [...rows].sort(activeSort.compare)
  }, [rows, activeSort])

  const ids = useMemo(() => sortedRows.map(rowId), [sortedRows, rowId])
  const openIndex = openId ? ids.indexOf(openId) : -1
  const openRow = openIndex >= 0 ? sortedRows[openIndex] : null
  const filtered = facets.some((facet) => searchParams.get(facet.param))

  // Reflect the open row in the URL so a refresh, a share, or Back lands on the same state — the
  // `${basePath}/${id}` route renders this same queue with `initialSelectedId` set. replaceState
  // rather than push: arrowing through fifty rows must not leave fifty history entries.
  const syncUrl = useCallback((id: string | null) => {
    if (typeof window === "undefined") return
    const qs = window.location.search
    window.history.replaceState(window.history.state, "", `${id ? `${basePath}/${id}` : basePath}${qs}`)
  }, [basePath])

  // Opening another row or closing the pane unmounts whatever is in it; unsaved work there
  // (Match manually's pending line matches, #250) gets one chance to say so.
  const open = useCallback((id: string) => { if (!confirmLeave()) return; setOpenId(id); syncUrl(id) }, [syncUrl])
  // Closing returns focus to the row that was open — recorded as state and applied in an effect
  // once the pane has unmounted, so `close` itself stays free of DOM refs.
  const [focusReturn, setFocusReturn] = useState<string | null>(null)
  const close = useCallback(() => {
    if (!confirmLeave()) return
    setFocusReturn(openId)
    setOpenId(null)
    syncUrl(null)
  }, [openId, syncUrl])
  useEffect(() => {
    if (openId === null && focusReturn) triggerRefs.current.get(focusReturn)?.focus()
  }, [openId, focusReturn])
  const step = useCallback((delta: 1 | -1) => {
    if (openIndex < 0) return
    const next = ids[openIndex + delta]
    if (next) open(next)
  }, [ids, openIndex, open])

  // The row a deep link asked for may have been filtered out or deleted; don't hold a pane open
  // on nothing. Derived, not synced: `openRow` is already null in that case, and the URL is
  // corrected the next time the operator opens or closes a row.

  // ↑/↓ move the selection and Escape closes, from anywhere on the screen except inside a field
  // the operator is typing in.
  useEffect(() => {
    if (!openId) return
    const onKey = (event: KeyboardEvent) => {
      const target = event.target as HTMLElement | null
      if (target?.closest("input, textarea, select, [contenteditable=true], [role=dialog], [role=listbox], [role=menu]")) return
      if (event.key === "ArrowDown") { event.preventDefault(); step(1) }
      else if (event.key === "ArrowUp") { event.preventDefault(); step(-1) }
      else if (event.key === "Escape") { event.preventDefault(); close() }
    }
    document.addEventListener("keydown", onKey)
    return () => document.removeEventListener("keydown", onKey)
  }, [openId, step, close])

  const checkedIds = [...checked].filter((id) => ids.includes(id))
  const allChecked = ids.length > 0 && checkedIds.length === ids.length
  const toggleChecked = (id: string) => setChecked((prev) => { const next = new Set(prev); if (next.has(id)) next.delete(id); else next.add(id); return next })
  const toggleAll = () => setChecked(allChecked ? new Set() : new Set(ids))
  const clearChecked = () => setChecked(new Set())

  const visibleColumns = openId ? columns.filter((column) => column.narrow) : columns
  const refresh = useCallback(() => { setReloadKey((k) => k + 1); router.refresh() }, [router])
  const helpers = useMemo<PaneHelpers>(() => ({ close, refresh }), [close, refresh])

  const setSort = (key: string) => {
    const next = new URLSearchParams(searchParams.toString())
    if (key === sortOptions[0]?.key) next.delete(sortParam); else next.set(sortParam, key)
    const qs = next.toString()
    router.push(qs ? `${pathname}?${qs}` : pathname)
  }

  const exportAll = async () => {
    if (!onExportAll) return
    setExporting(true)
    try { await onExportAll() } catch { toast.error("Could not reach the server") } finally { setExporting(false) }
  }

  // The screen is viewport-bound from `md` up so the queue and the pane scroll independently
  // under a sticky table head (the app shell's root is `min-h-screen`, which alone would let the
  // pane grow past the viewport and push its action bar out of reach). Below `md` the queue
  // flows with the page and the pane is a fixed sheet, so no bound is needed.
  return <div ref={rootRef} className="flex min-h-0 flex-1 flex-col md:h-dvh md:flex-none md:overflow-hidden">
    {/* Row 1: title · Views · Sort · filters · stat · menu */}
    <div className="flex flex-wrap items-center gap-x-3 gap-y-2 border-b border-slate-200 px-4 py-2">
      <h1 className="flex items-baseline gap-2 text-lg font-semibold tracking-tight text-slate-900">
        {title}
        <span className="text-sm font-normal tabular-nums text-slate-500" aria-label={`${rows.length} rows`}>{rows.length}</span>
      </h1>
      {views}
      {sortOptions.length > 1 && <label className="inline-flex h-8 items-center gap-1 rounded-md border border-slate-300 bg-white pl-2 pr-1 text-xs font-medium text-slate-700 focus-within:ring-2 focus-within:ring-emerald-600 focus-within:ring-offset-1">
        <ArrowUpDown className="h-3.5 w-3.5 text-slate-500" aria-hidden />
        <span className="sr-only">Sort by</span>
        <select value={activeSort?.key} onChange={(event) => setSort(event.target.value)} className="h-full cursor-pointer appearance-none bg-transparent pr-1 text-xs font-medium text-slate-700 focus:outline-none">
          {sortOptions.map((option) => <option key={option.key} value={option.key}>{option.label}</option>)}
        </select>
      </label>}
      {facets.length > 0 && <FacetFilters facets={facets} />}
      <div className="ml-auto flex items-center gap-2">
        {stat}
        <Popover open={menuOpen} onOpenChange={setMenuOpen}>
          <PopoverTrigger asChild>
            <button type="button" aria-label="Queue options" className="inline-flex h-8 w-8 items-center justify-center rounded-md text-slate-600 hover:bg-slate-100 hover:text-slate-900 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-600">
              <MoreHorizontal className="h-4 w-4" aria-hidden />
            </button>
          </PopoverTrigger>
          <PopoverContent align="end" className="w-72 p-1" onClick={(event) => { if ((event.target as HTMLElement).closest("[data-menu-close]")) setMenuOpen(false) }}>
            <button type="button" role="switch" aria-checked={overrideMode.active} onClick={overrideMode.toggle} data-menu-close
              className="flex w-full items-start gap-2.5 rounded-sm px-2.5 py-2 text-left text-sm text-slate-700 hover:bg-slate-100">
              {overrideMode.active ? <ShieldCheck className="mt-0.5 h-4 w-4 shrink-0 text-amber-700" aria-hidden /> : <ShieldAlert className="mt-0.5 h-4 w-4 shrink-0 text-slate-500" aria-hidden />}
              <span>
                <span className="block font-medium">{overrideMode.active ? "Turn off Override Mode" : "Turn on Override Mode"}</span>
                <span className="block text-xs text-slate-500">Lets you override soft checks (match, confidence, trust, workspace) with a reason. Duplicate, jurisdiction and SMB-ceiling checks never can be.</span>
              </span>
            </button>
            {onExportAll && <button type="button" onClick={() => void exportAll()} disabled={exporting || rows.length === 0} data-menu-close
              className="flex w-full items-center gap-2.5 rounded-sm px-2.5 py-2 text-left text-sm text-slate-700 hover:bg-slate-100 disabled:opacity-50">
              <Download className="h-4 w-4 shrink-0 text-slate-500" aria-hidden />
              {exporting ? "Exporting…" : `Export ${rows.length === 1 ? "this row" : `all ${rows.length} rows`} as CSV`}
            </button>}
            {menu}
          </PopoverContent>
        </Popover>
      </div>
    </div>

    {/* Override Mode banner — only while the mode is on (#203's permanent strip is gone). */}
    {overrideMode.active && <div role="status" className="flex flex-wrap items-center justify-between gap-2 border-b border-amber-200 bg-amber-50 px-4 py-1.5 text-xs font-medium text-amber-900">
      <span className="inline-flex items-center gap-1.5"><ShieldCheck className="h-3.5 w-3.5" aria-hidden />Override Mode is on. Open a row&apos;s Checks tab to override a soft check with a reason.</span>
      <button type="button" onClick={overrideMode.toggle} className="rounded-md border border-amber-300 bg-white px-2 py-0.5 text-xs font-medium text-amber-900 hover:bg-amber-100">Turn off</button>
    </div>}

    {/* Bulk action bar: its own row above the table head once anything is checked. */}
    {selectable && bulkActions && checkedIds.length > 0 && <div className="flex flex-wrap items-center gap-2 border-b border-slate-200 bg-slate-50 px-4 py-2 text-sm" role="region" aria-label="Bulk actions">
      <span className="mr-1 font-medium tabular-nums text-slate-800">{checkedIds.length} selected</span>
      {bulkActions({ selectedIds: checkedIds, clear: clearChecked })}
      <button type="button" onClick={clearChecked} className="ml-auto text-xs font-medium text-slate-600 hover:text-slate-900">Clear selection</button>
    </div>}

    <div className="flex min-h-0 flex-1 md:overflow-hidden">
      <div className={`min-w-0 flex-1 md:overflow-auto ${openId ? "lg:shadow-[inset_-1px_0_0_0_rgb(226_232_240)]" : ""}`}>
        {sortedRows.length === 0
          ? <div className="mx-auto max-w-md px-6 py-16 text-center">
            <p className="text-sm font-medium text-slate-800">{filtered ? empty.filteredTitle ?? "Nothing matches these filters." : empty.title}</p>
            <p className="mt-1 text-sm text-slate-600">{filtered ? empty.filteredBody ?? "Clear a filter to widen the queue." : empty.body}</p>
          </div>
          : <table className={`w-full text-sm ${openId ? "" : "min-w-[720px]"}`}>
            <thead className="sticky top-0 z-10 bg-white shadow-[inset_0_-1px_0_0_theme(colors.slate.200)]">
              <tr className="text-left text-xs font-medium uppercase tracking-wide text-slate-600">
                {selectable && <th scope="col" className="w-10 px-3 py-2">
                  <input type="checkbox" aria-label={`Select all ${title.toLowerCase()}`} checked={allChecked} onChange={toggleAll} className="h-4 w-4 rounded border-slate-300 accent-emerald-700" />
                </th>}
                {leading && <th scope="col" className="w-8 px-1 py-2"><span className="sr-only">Mark</span></th>}
                {visibleColumns.map((column) => <th key={column.key} scope="col" className={`px-3 py-2 font-medium ${column.className ?? ""}`}>{column.label}</th>)}
              </tr>
            </thead>
            <tbody>
              {sortedRows.map((row) => {
                const id = rowId(row)
                const isOpen = id === openId
                const isChecked = checked.has(id)
                return <tr key={id} aria-current={isOpen ? "true" : undefined} style={{ height: 62 }}
                  className={`group cursor-pointer border-b border-slate-100 transition-colors ${isOpen ? "bg-emerald-50/60" : isChecked ? "bg-slate-50" : "hover:bg-slate-50"}`}
                  onClick={(event) => {
                    if ((event.target as HTMLElement).closest(INTERACTIVE)) return
                    if (isOpen) close(); else open(id)
                  }}>
                  {selectable && <td className="px-3 py-0">
                    <input type="checkbox" aria-label={`Select ${rowTitle(row)}`} checked={isChecked} onChange={() => toggleChecked(id)} className="h-4 w-4 rounded border-slate-300 accent-emerald-700" />
                  </td>}
                  {leading && <td className="px-1 py-0">{leading(row)}</td>}
                  {visibleColumns.map((column, columnIndex) => <td key={column.key} className={`px-3 py-0 ${column.className ?? ""} ${isOpen && columnIndex === 0 ? "relative before:absolute before:inset-y-2 before:-left-px before:w-[3px] before:rounded-full before:bg-emerald-700" : ""}`}>
                    {columnIndex === 0
                      ? <button type="button" ref={(el) => { if (el) triggerRefs.current.set(id, el); else triggerRefs.current.delete(id) }}
                        aria-expanded={isOpen} aria-controls={DETAIL_PANE_ID}
                        aria-label={[rowTitle(row), rowSubtitle?.(row)].filter(Boolean).join(" · ")}
                        onClick={() => (isOpen ? close() : open(id))}
                        className="block w-full min-w-0 rounded-sm text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-600 focus-visible:ring-offset-2">
                        {column.render(row)}
                      </button>
                      : column.render(row)}
                  </td>)}
                </tr>
              })}
            </tbody>
          </table>}
      </div>

      {openRow && <DetailPane
        documentId={(detailIdFor ?? rowId)(openRow)}
        title={rowTitle(openRow)}
        subtitle={rowSubtitle?.(openRow) ?? null}
        position={{ index: openIndex + 1, total: sortedRows.length }}
        onClose={close}
        onPrev={openIndex > 0 ? () => step(-1) : null}
        onNext={openIndex < sortedRows.length - 1 ? () => step(1) : null}
        loadDetail={loadDetail}
        actions={paneActions?.(openRow, helpers)}
        menu={paneMenu?.(openRow, helpers)}
        reloadKey={reloadKey} />}
    </div>
  </div>
}

"use client"

import { useRef, useState, type ReactNode } from "react"
import { useRouter } from "next/navigation"
import { toast } from "sonner"
import { ExternalLink } from "lucide-react"
import { Button } from "@/components/ui/button"
import { ConfirmDialog } from "@/components/ui/confirm-dialog"
import { QueueScreen, type QueueColumn, type SortOption } from "@/components/queue/queue-screen"
import { PaneMenuItem } from "@/components/queue/detail-pane"
import { DocumentBulkActions, DocumentPaneActions } from "@/components/queue/document-actions"
import { formatDate, formatMoney, StatePills, TitleCell } from "@/components/queue/row-cells"
import { PoChip, useOriginHere } from "@/components/documents/po-compare"
import { ReasonDialog } from "@/components/list-screen/reason-dialog-button"
import type { Facet } from "@/components/queue/facet-filters"
import { ConfidenceField, ProcessingStateGlyph } from "@/components/typed-destinations/row-signals"
import { processingState } from "@/lib/documents/processing-state"
import { EligibilityStrip, ItemizedRecapTable, type ItemizedRecord } from "@/components/typed-destinations/bulk-approve-receipt"
import { DueDateCountdownBadge, ReviewSlaCountdownBadge } from "@/components/documents/countdown-badge"
import { DEFAULT_REVIEW_SLA_HOURS } from "@/lib/documents/countdown"
import { minConfidenceFromPercent } from "@/lib/documents/confidence-state"
import { bulkExportDocumentsAction } from "@/app/(app)/workspaces/[workspaceId]/pipeline-actions"
import { cancelInvoiceAction } from "@/app/(app)/workspaces/[workspaceId]/actions"
import { getQueueDetailAction } from "@/app/(app)/workspaces/[workspaceId]/queue-actions"
import { downloadCsv } from "@/lib/client/download-csv"
import type { BillRow } from "@/models/bills"

/** #225: the Invoices queue on the shared Queue screen. Status and Invoice Approval keep #211's
 * taxonomy, now as summary chips over a hierarchical facet panel (Open sub-states vs Closed);
 * Aging joins them as a chip group in place of #186's six header cards. */
export const INVOICE_FACETS: Facet[] = [
  {
    param: "status", label: "Status",
    sections: [
      { label: "Open", options: [{ value: "unreviewed", label: "Unreviewed" }, { value: "reviewed", label: "Reviewed" }, { value: "synced", label: "Synced" }] },
      { label: "Closed", options: [{ value: "paid", label: "Paid" }] },
    ],
  },
  {
    param: "approval", label: "Invoice Approval",
    options: [
      { value: "not_started", label: "Not started" }, { value: "in_progress", label: "In progress" }, { value: "approved", label: "Approved" },
      { value: "rejected", label: "Rejected" }, { value: "cancelled", label: "Cancelled" },
    ],
  },
  {
    param: "aging", label: "Aging", kind: "multi",
    options: [
      { value: "current", label: "Current" }, { value: "1-30", label: "1–30 days overdue" }, { value: "31-60", label: "31–60 days" },
      { value: "61-90", label: "61–90 days" }, { value: "90+", label: "90+ days" }, { value: "none", label: "No due date" },
    ],
  },
  // #228 Q6: the Purchase Orders facet. Matched = a compared PO with nothing red; No PO = nothing
  // compared (none, a suggestion only, or a rejected link); Mismatch = a compared PO with `≠`s.
  { param: "po", label: "PO", options: [{ value: "matched", label: "Matched" }, { value: "none", label: "No PO" }, { value: "mismatch", label: "Mismatch" }] },
  { param: "blocked", label: "Needs attention", kind: "toggle", options: [{ value: "1", label: "Needs attention only" }] },
  { param: "unpaid", label: "Unpaid", kind: "toggle", options: [{ value: "1", label: "Unpaid only" }] },
  { param: "touchless", label: "Touchless", kind: "toggle", options: [{ value: "1", label: "Touchless only" }] },
]

function poSubtitle(bill: BillRow): string | null {
  const po = bill.po
  if (po.removed) return "PO removed"
  if (!po.kind) return null
  if (po.kind === "suggested") return po.suggestionCount > 1 ? `${po.suggestionCount} likely POs` : `Likely ${po.poNumber ?? "PO"}`
  return `${po.poNumber ?? "PO"}${po.mismatchCount ? ` · ${po.mismatchCount} mismatch${po.mismatchCount === 1 ? "" : "es"}` : ""}`
}

const SORTS: SortOption<BillRow>[] = [
  { key: "newest", label: "Newest first", compare: () => 0 },
  { key: "due", label: "Due date", compare: (a, b) => (a.dueDate?.getTime() ?? Infinity) - (b.dueDate?.getTime() ?? Infinity) },
  { key: "amount", label: "Amount, high to low", compare: (a, b) => (b.total ?? -Infinity) - (a.total ?? -Infinity) },
  { key: "supplier", label: "Supplier A–Z", compare: (a, b) => (a.supplier ?? "￿").localeCompare(b.supplier ?? "￿") },
]

export function InvoiceQueue({ workspaceId, basePath, bills, payableDocumentIds, preparePaymentRunAction, minConfidencePercent, views, stat, initialSelectedId }: {
  workspaceId: string
  basePath: string
  bills: BillRow[]
  payableDocumentIds: string[]
  preparePaymentRunAction: (formData: FormData) => Promise<void>
  minConfidencePercent: number
  views?: ReactNode
  stat?: ReactNode
  initialSelectedId?: string | null
}) {
  const router = useRouter()
  const origin = useOriginHere()
  const [needsAttention, setNeedsAttention] = useState<Set<string>>(new Set())
  const [cancelling, setCancelling] = useState<BillRow | null>(null)
  const minConfidence = minConfidenceFromPercent(minConfidencePercent)
  const billsById = new Map(bills.map((bill) => [bill.documentId, bill]))
  const toRecord = (id: string): ItemizedRecord => {
    const bill = billsById.get(id)
    return { id, type: "Invoice", vendor: bill?.supplier ?? null, number: bill?.invoiceNumber ?? null, amount: bill?.total ?? null, currencyCode: bill?.currencyCode ?? null, dateLabel: "Due", date: bill?.dueDate ?? null }
  }

  const columns: QueueColumn<BillRow>[] = [
    {
      key: "supplier", label: "Supplier", narrow: true, className: "min-w-[12rem]",
      render: (bill) => <TitleCell subtitle={bill.filename} missingLabel="Unknown supplier"
        title={bill.supplier ? <ConfidenceField label="Supplier" value={bill.fieldConfidence.vendor ?? bill.fieldConfidence.merchant} minConfidence={minConfidence}>{bill.supplier}</ConfidenceField> : null} />,
    },
    {
      key: "number", label: "Invoice #", className: "whitespace-nowrap text-slate-700",
      render: (bill) => <ConfidenceField label="Invoice number" value={bill.invoiceNumber ? bill.fieldConfidence.invoice_number : undefined} minConfidence={minConfidence}>{bill.invoiceNumber ?? "—"}</ConfidenceField>,
    },
    {
      key: "amount", label: "Amount", narrow: true, className: "whitespace-nowrap text-right tabular-nums text-slate-900",
      render: (bill) => <ConfidenceField label="Amount" value={bill.total !== null ? bill.fieldConfidence.total ?? bill.fieldConfidence.amount : undefined} minConfidence={minConfidence}>{bill.total !== null ? formatMoney(bill.total, bill.currencyCode) : "—"}</ConfidenceField>,
    },
    {
      key: "due", label: "Due", narrow: true, className: "whitespace-nowrap tabular-nums text-slate-700",
      render: (bill) => <>
        <ConfidenceField label="Due date" value={bill.extractedDueDate ? bill.fieldConfidence.due_date : undefined} minConfidence={minConfidence}>{formatDate(bill.dueDate)}</ConfidenceField>
        {bill.dueDate && !bill.extractedDueDate && <span className="ml-1.5 text-xs text-slate-500" title="From the supplier's payment terms, not the document">inferred</span>}
      </>,
    },
    { key: "aging", label: "Aging", className: "whitespace-nowrap", render: (bill) => <DueDateCountdownBadge dueDate={bill.dueDate} /> },
    {
      // #228 Q5/Q6/Q11: the matched PO as a chip carrying the number of `≠` glyphs the pane will
      // show; dashed for a suggestion that compares nothing; "PO removed" after a rejection.
      key: "po", label: "Purchase Orders", narrow: true, className: "whitespace-nowrap",
      render: (bill) => <PoChip poNumber={bill.po.poNumber} kind={bill.po.kind} mismatchCount={bill.po.mismatchCount} confidence={bill.po.confidence ?? undefined}
        suggestionCount={bill.po.suggestionCount} removed={bill.po.removed} origin={origin}
        href={bill.po.kind && bill.po.kind !== "suggested" && bill.po.poDocumentId ? `/workspaces/${workspaceId}/purchase-orders/${bill.po.poDocumentId}` : undefined} />,
    },
    {
      key: "state", label: "State",
      render: (bill) => <StatePills minConfidencePercent={minConfidencePercent}
        cancelled={!!bill.cancelledAt} cancelledReason={bill.cancelledReason}
        needsAttention={bill.blockedByCheck || needsAttention.has(bill.documentId) || bill.approvalStatus === "rejected"} openCheckCodes={bill.openCheckCodes}
        inReview={bill.approvalStatus === "in_progress"} touchless={bill.touchless} approved={bill.status === "reviewed"}
        ledger={bill.paymentStatus}
        trailing={<ReviewSlaCountdownBadge openedAt={bill.reviewTaskOpenedAt} slaHours={DEFAULT_REVIEW_SLA_HOURS} />} />,
    },
  ]

  const exportAll = async () => {
    const result = await bulkExportDocumentsAction(workspaceId, bills.map((bill) => bill.documentId))
    if (!result.success || !result.data) { toast.error(result.error || "Export failed"); return }
    downloadCsv(result.data.csv, "invoices.csv")
    toast.success(`Exported ${bills.length} invoices`)
  }

  const cancelInfo = (bill: BillRow) => {
    if (bill.cancelledAt) return null
    const status = bill.paymentStatus?.toLowerCase() ?? null
    if (status === "synced") return { canCancel: false, reason: "Already synced to your ledger, so it can no longer be cancelled." }
    if (status === "paid" || status === "reconciled") return { canCancel: false, reason: "Already paid, so it can no longer be cancelled." }
    return { canCancel: true, reason: null }
  }

  return <>
    <QueueScreen<BillRow>
      title="Invoices"
      basePath={basePath}
      rows={bills}
      rowId={(bill) => bill.documentId}
      rowTitle={(bill) => bill.supplier ?? "Unknown supplier"}
      // #228 Q6: the PO folds into the card's second line below `md` (and the row's name), so a
      // phone reviewer hears the red count without the column.
      rowSubtitle={(bill) => [bill.invoiceNumber, bill.total !== null ? formatMoney(bill.total, bill.currencyCode) : null, poSubtitle(bill)].filter(Boolean).join(" · ") || bill.filename}
      // #223: the leading edge is the five-state processing glyph, not the aging bucket (aging lives
      // in the countdown badge's own text since #208).
      leading={(bill) => <ProcessingStateGlyph
        state={processingState({ approvalStatus: bill.approvalStatus, blockedByCheck: bill.blockedByCheck, escalated: bill.escalated, touchless: bill.touchless, status: bill.status })}
        minConfidencePercent={minConfidencePercent} />}
      columns={columns}
      selectable
      sortOptions={SORTS}
      facets={INVOICE_FACETS}
      views={views}
      stat={stat}
      onExportAll={exportAll}
      initialSelectedId={initialSelectedId}
      empty={{ title: "No invoices yet.", body: "Invoices appear here once one is extracted from an upload or an inbound email.", filteredBody: "Clear a filter to widen the queue." }}
      loadDetail={(documentId) => getQueueDetailAction(workspaceId, documentId)}
      bulkActions={({ selectedIds, clear }) => <DocumentBulkActions
        workspaceId={workspaceId} noun="invoice" selectedIds={selectedIds} clear={clear} toRecord={toRecord}
        eligibleIds={selectedIds.filter((id) => !billsById.get(id)?.blockedByCheck)} exportFilename="invoices.csv"
        onHeldBack={(heldBack, approved) => setNeedsAttention((prev) => { const next = new Set(prev); for (const id of heldBack) next.add(id); for (const id of approved) next.delete(id); return next })}
        extra={<PaymentRunAction selectedIds={selectedIds} payableDocumentIds={payableDocumentIds} preparePaymentRunAction={preparePaymentRunAction} toRecord={toRecord} />} />}
      paneActions={(bill, { refresh }) => <DocumentPaneActions workspaceId={workspaceId} documentId={bill.documentId} noun="invoice"
        status={bill.status} openReviewTaskId={bill.openReviewTaskId} cancelled={!!bill.cancelledAt} onDone={refresh} />}
      paneMenu={(bill) => {
        const info = cancelInfo(bill)
        return <>
          <PaneMenuItem onClick={() => window.open(`${basePath}/${bill.documentId}?full=1`, "_blank", "noopener")}>
            <ExternalLink className="mr-2 h-4 w-4 text-slate-500" aria-hidden />Open in a new tab
          </PaneMenuItem>
          {info && <PaneMenuItem tone="amber" disabled={!info.canCancel} hint={info.reason ?? undefined} onClick={() => setCancelling(bill)}>Cancel invoice…</PaneMenuItem>}
        </>
      }} />

    <ReasonDialog open={cancelling !== null} onClose={() => setCancelling(null)}
      action={async (formData) => {
        if (!cancelling) return { success: false, error: "No invoice selected" }
        const result = await cancelInvoiceAction(workspaceId, cancelling.documentId, formData)
        if (result.success) { toast.success("Invoice cancelled"); router.refresh() }
        return result
      }}
      title="Cancel this invoice"
      description="This is final. There is no way to un-cancel once confirmed. The reason is recorded on the audit trail."
      submitLabel="Cancel invoice"
      placeholder="Why is this invoice being cancelled?" />
  </>
}

/** Invoices' surface-specific bulk action: the payment-run file for the eligible selection. */
function PaymentRunAction({ selectedIds, payableDocumentIds, preparePaymentRunAction, toRecord }: {
  selectedIds: string[]
  payableDocumentIds: string[]
  preparePaymentRunAction: (formData: FormData) => Promise<void>
  toRecord: (id: string) => ItemizedRecord
}) {
  const [confirming, setConfirming] = useState(false)
  const formRef = useRef<HTMLFormElement>(null)
  const payable = selectedIds.filter((id) => payableDocumentIds.includes(id))
  if (payable.length === 0) return null
  return <>
    <form ref={formRef} action={preparePaymentRunAction} className="hidden">
      {payable.map((id) => <input key={id} type="hidden" name="documentId" value={id} />)}
    </form>
    <Button type="button" size="sm" variant="outline" onClick={() => setConfirming(true)}>Prepare payment run ({payable.length})</Button>
    <ConfirmDialog
      open={confirming}
      title={`Prepare a payment run for ${payable.length} invoice${payable.length === 1 ? "" : "s"}?`}
      description="Downloads a payment file for the eligible invoices below. No money moves."
      confirmLabel={`Prepare payment run (${payable.length})`}
      onConfirm={() => { setConfirming(false); formRef.current?.requestSubmit() }}
      onCancel={() => setConfirming(false)}>
      <div className="space-y-2">
        <EligibilityStrip eligible={payable.length} total={selectedIds.length} />
        <ItemizedRecapTable records={payable.map(toRecord)} />
      </div>
    </ConfirmDialog>
  </>
}

import { getCurrentUser } from "@/lib/auth"
import { listWorkspaceBills, type BillRow } from "@/models/bills"
import { getMinConfidencePercent } from "@/models/automation-config"
import { requireWorkspaceRole, type WorkspaceRole } from "@/models/workspaces"
import { listSavedViews } from "@/models/saved-views"
import { createSavedViewAction, deleteSavedViewAction, duplicateSavedViewAction, renameSavedViewAction, saveFiltersToViewAction, shareSavedViewAction } from "@/app/(app)/workspaces/[workspaceId]/(chrome)/saved-views-actions"
import { preparePaymentRunAction } from "@/app/(app)/workspaces/[workspaceId]/(chrome)/bills/actions"
import { InvoiceQueue } from "@/components/queue/invoice-queue"
import { QueueStat } from "@/components/queue/queue-stat"
import { SavedViewPicker } from "@/components/typed-destinations/saved-view-picker"
import { getTouchlessRateTrend } from "@/lib/analytics/workspace-analytics"
import type { AgingBucket } from "@/lib/bills/due-date"

export const dynamic = "force-dynamic"

export type InvoiceSearchParams = { blocked?: string; unpaid?: string; status?: string; approval?: string; touchless?: string; aging?: string; po?: string; view?: string; sort?: string }

/** #225: Invoices on the Queue screen. Filters stay plain URL params (shareable, refreshable,
 * saveable as a view); the aging chip group filters here after the fetch since `agingBucket` is
 * derived per row, and the per-bucket totals now live on the Dashboard. */
export async function InvoicesQueuePage({ params, searchParams, selectedDocumentId = null }: {
  params: Promise<{ workspaceId: string }>
  searchParams: Promise<InvoiceSearchParams>
  selectedDocumentId?: string | null
}) {
  const { workspaceId } = await params
  const { blocked, unpaid, status, approval, touchless, aging, po, view: selectedViewId } = await searchParams
  const user = await getCurrentUser()
  const membership = await requireWorkspaceRole(workspaceId, user.id)
  const isOwner = membership.role === "owner"

  const onlyBlocked = blocked === "1"
  const onlyUnpaid = unpaid === "1"
  const onlyTouchless = touchless === "1"
  const statusFilter = status === "unreviewed" || status === "reviewed" || status === "synced" || status === "paid" ? status : undefined
  const approvalFilter: BillRow["approvalStatus"] | undefined =
    approval === "not_started" || approval === "in_progress" || approval === "approved" || approval === "rejected" || approval === "cancelled" ? approval : undefined
  const agingFilter = new Set((aging ?? "").split(",").filter((value): value is AgingBucket | "none" => ["current", "1-30", "31-60", "61-90", "90+", "none"].includes(value)))
  const poFilter = po === "matched" || po === "none" || po === "mismatch" ? po : undefined
  const basePath = `/workspaces/${workspaceId}/invoices`
  const [{ bills: allBills }, minConfidencePercent, savedViews, touchlessTrend] = await Promise.all([
    listWorkspaceBills({ workspaceId, onlyBlocked, onlyUnpaid, statusFilter, approvalFilter, onlyTouchless, poFilter }),
    getMinConfidencePercent(workspaceId),
    listSavedViews({ workspaceId, viewKey: "invoices", userId: user.id }),
    getTouchlessRateTrend(workspaceId),
  ])
  const bills = agingFilter.size === 0 ? allBills : allBills.filter((bill) => agingFilter.has(bill.agingBucket ?? "none"))
  const currentViewFilters: Record<string, string> = {
    ...(onlyBlocked ? { blocked: "1" } : {}), ...(onlyUnpaid ? { unpaid: "1" } : {}),
    ...(onlyTouchless ? { touchless: "1" } : {}), ...(statusFilter ? { status: statusFilter } : {}),
    ...(approvalFilter ? { approval: approvalFilter } : {}), ...(agingFilter.size ? { aging: [...agingFilter].join(",") } : {}),
    ...(poFilter ? { po: poFilter } : {}),
  }
  // Only bills with a total AND an unblocked status are candidates for a payment run. #220: a
  // cancelled invoice is excluded too. "synced" (pushed but unconfirmed) stays eligible.
  const payableBills = bills.filter((b) => !b.blockedByCheck && !b.cancelledAt && b.total !== null && b.total > 0 && (!b.paymentStatus || !["paid", "reconciled"].includes(b.paymentStatus.toLowerCase())))
  const payableDocumentIds = isOwner ? payableBills.map((bill) => bill.documentId) : []
  const trend = touchlessTrend.trend ? `${touchlessTrend.trend.deltaPercentagePoints > 0 ? "+" : ""}${touchlessTrend.trend.deltaPercentagePoints}pt` : null

  return <InvoiceQueue
    workspaceId={workspaceId}
    basePath={basePath}
    bills={bills}
    payableDocumentIds={payableDocumentIds}
    preparePaymentRunAction={preparePaymentRunAction.bind(null, workspaceId)}
    minConfidencePercent={minConfidencePercent}
    initialSelectedId={selectedDocumentId}
    stat={<QueueStat label="Touchless" value={`${Math.round(touchlessTrend.touchlessRate * 100)}%`}
      detail={`${touchlessTrend.totalPushedTouchless} of ${touchlessTrend.totalExtracted} sent without review, last 30 days${trend ? `, ${trend} vs. prior 30` : ""}`}
      trend={touchlessTrend.trend?.direction ?? null} />}
    views={<SavedViewPicker views={savedViews} selectedViewId={selectedViewId ?? null} currentFilters={currentViewFilters}
      currentUserId={user.id} currentUserRole={membership.role as WorkspaceRole}
      createAction={createSavedViewAction.bind(null, workspaceId, "invoices", basePath)}
      duplicateAction={duplicateSavedViewAction.bind(null, workspaceId, "invoices", basePath)}
      renameAction={renameSavedViewAction.bind(null, workspaceId, basePath)}
      saveFiltersAction={saveFiltersToViewAction.bind(null, workspaceId, basePath)}
      deleteAction={deleteSavedViewAction.bind(null, workspaceId, basePath)}
      shareAction={shareSavedViewAction.bind(null, workspaceId, basePath)} />} />
}

export default function InvoicesPage({ params, searchParams }: { params: Promise<{ workspaceId: string }>; searchParams: Promise<InvoiceSearchParams> }) {
  return InvoicesQueuePage({ params, searchParams })
}

// Deliberately NOT a "use server" module: server actions live upstream and do the auth.
import { prisma } from "@/lib/db"
import { recordSystemAudit } from "@/lib/audit"
import { listWorkspaceBills } from "@/models/bills"
import { formatZaEftCsv, paymentRunFilename, totalsByCurrency, type PaymentInstruction } from "@/lib/payments/za-eft-csv"
import { buildRemittanceAdvices, type RemittanceAdvice } from "@/lib/payments/remittance"
import type { Prisma } from "@/prisma/client"

export type PreparePaymentRunResult = {
  run: { id: string; filename: string; itemCount: number; totalsByCurrency: Record<string, number> }
  csv: string
  advices: RemittanceAdvice[]
}

/** WP-AP2: prepares a payment run from the given bills for this workspace. Filters out bills
 * that are already in an active (non-cancelled) run so the same invoice isn't paid twice, and
 * returns the generated CSV + per-supplier remittance advices. Never itself moves money — the
 * user takes the CSV to their bank's own portal.
 *
 * Bills without a supplier bank account are dropped from the run rather than blocking it — the
 * caller renders the "N bills need a bank account" hint separately. */
export async function preparePaymentRun(input: {
  workspaceId: string
  actorId: string
  documentIds: string[]
  now?: Date
}): Promise<PreparePaymentRunResult> {
  const now = input.now ?? new Date()
  if (input.documentIds.length === 0) throw new Error("no_documents_selected")

  const { bills } = await listWorkspaceBills({ workspaceId: input.workspaceId, limit: 1000 })
  const selectedIds = new Set(input.documentIds)
  const selected = bills.filter((b) => selectedIds.has(b.documentId))

  const alreadyInRun = await prisma.paymentRunItem.findMany({
    where: { workspaceId: input.workspaceId, documentId: { in: input.documentIds }, active: true },
    select: { documentId: true },
  })
  const alreadyIds = new Set(alreadyInRun.map((r) => r.documentId).filter(Boolean) as string[])

  const suppliers = await prisma.supplier.findMany({
    where: { workspaceId: input.workspaceId, id: { in: selected.map((b) => b.supplierId).filter((id): id is string => id !== null) } },
    select: { id: true, iban: true, bankDetails: true },
  })
  const bankBySupplier = new Map(suppliers.map((s) => {
    const details = (s.bankDetails ?? {}) as Record<string, unknown>
    const account = typeof details.account === "string" ? details.account : (typeof details.iban === "string" ? details.iban : (typeof s.iban === "string" ? s.iban : null))
    const branchCode = typeof details.branchCode === "string" ? details.branchCode : (typeof details.branch === "string" ? details.branch : null)
    return [s.id, { account, branchCode }]
  }))

  const instructions: PaymentInstruction[] = []
  const skipped: Array<{ documentId: string; reason: string }> = []
  for (const bill of selected) {
    if (alreadyIds.has(bill.documentId)) { skipped.push({ documentId: bill.documentId, reason: "already_in_active_run" }); continue }
    // #220: server-side defense in depth — the client already excludes a cancelled invoice from
    // payableDocumentIds, but a payment file is money leaving the workspace, so this doesn't rely
    // on that alone.
    if (bill.cancelledAt) { skipped.push({ documentId: bill.documentId, reason: "cancelled" }); continue }
    if (bill.total === null || bill.total <= 0) { skipped.push({ documentId: bill.documentId, reason: "missing_amount" }); continue }
    if (!bill.supplier) { skipped.push({ documentId: bill.documentId, reason: "missing_supplier" }); continue }
    const bank = bill.supplierId ? bankBySupplier.get(bill.supplierId) : null
    if (!bank?.account) { skipped.push({ documentId: bill.documentId, reason: "missing_bank_account" }); continue }
    instructions.push({
      documentId: bill.documentId,
      supplier: bill.supplier,
      bankAccountNumber: bank.account,
      branchCode: bank.branchCode ?? null,
      amount: bill.total,
      currencyCode: (bill.currencyCode ?? "ZAR").toUpperCase(),
      reference: bill.invoiceNumber ?? bill.documentId.slice(0, 8),
    })
  }

  if (instructions.length === 0) throw new Error("no_payable_bills_after_filtering")

  const csv = formatZaEftCsv(instructions)
  const filename = paymentRunFilename(now)
  const totals = totalsByCurrency(instructions)

  const workspace = await prisma.workspace.findFirst({ where: { id: input.workspaceId }, select: { name: true } })
  const advices = buildRemittanceAdvices(instructions, { name: workspace?.name ?? "Your workspace", runDate: now })

  const run = await prisma.paymentRun.create({
    data: {
      workspaceId: input.workspaceId,
      createdById: input.actorId,
      status: "draft",
      filename,
      itemCount: instructions.length,
      totalsJson: totals as unknown as Prisma.InputJsonValue,
      items: {
        create: instructions.map((ins) => ({
          workspaceId: input.workspaceId,
          documentId: ins.documentId,
          supplier: ins.supplier,
          amount: ins.amount,
          currencyCode: ins.currencyCode,
          reference: ins.reference,
        })),
      },
    },
    select: { id: true, filename: true, itemCount: true },
  })

  await recordSystemAudit({
    workspaceId: input.workspaceId,
    type: "payment_run_prepared",
    detail: { runId: run.id, itemCount: run.itemCount, skipped, totalsByCurrency: totals },
  })

  return {
    run: { id: run.id, filename: run.filename ?? filename, itemCount: run.itemCount, totalsByCurrency: totals },
    csv,
    advices,
  }
}

/** Marks a draft run as sent to the bank. Called from the "I've uploaded it" server action, so
 * the aging view knows not to keep flagging the bills as unpaid until the ledger sync catches
 * up. Ledger reconciliation itself is unchanged — bank-match matches the payment lines back to
 * these documents through their invoice references, exactly like it does today for manually-paid
 * bills. */
export async function markPaymentRunSent(input: { workspaceId: string; runId: string; actorId: string }) {
  const run = await prisma.paymentRun.findFirst({ where: { id: input.runId, workspaceId: input.workspaceId }, select: { id: true, status: true } })
  if (!run) throw new Error("payment_run_not_found")
  if (run.status !== "draft") throw new Error("payment_run_not_draft")
  const updated = await prisma.paymentRun.update({
    where: { id: run.id },
    data: { status: "sent", sentAt: new Date() },
    select: { id: true, status: true, sentAt: true },
  })
  await recordSystemAudit({
    workspaceId: input.workspaceId,
    type: "payment_run_sent",
    detail: { runId: run.id, actorId: input.actorId },
  })
  return updated
}

export async function listPaymentRuns(workspaceId: string, opts: { limit?: number } = {}) {
  return prisma.paymentRun.findMany({
    where: { workspaceId },
    orderBy: { createdAt: "desc" },
    take: opts.limit ?? 50,
    select: { id: true, filename: true, status: true, itemCount: true, totalsJson: true, sentAt: true, createdAt: true },
  })
}

"use server"

import { getCurrentUser } from "@/lib/auth"
import { requireWorkspaceRole } from "@/models/workspaces"
import { preparePaymentRun } from "@/models/payment-runs"
import { revalidatePath } from "next/cache"
import { redirect } from "next/navigation"

/** WP-AP2: Bills-page server action to prepare a ZA EFT payment file from a set of bill IDs.
 * The action creates the PaymentRun + items and redirects to the download route, which
 * regenerates the CSV from the stored rows. Owner-only — payments are a controller action. */
export async function preparePaymentRunAction(workspaceId: string, formData: FormData) {
  const user = await getCurrentUser()
  const membership = await requireWorkspaceRole(workspaceId, user.id)
  if (membership.role !== "owner") throw new Error("owner_only")

  const documentIds = formData.getAll("documentId").map(String).filter(Boolean)
  if (!documentIds.length) throw new Error("no_documents_selected")

  const { run } = await preparePaymentRun({ workspaceId, actorId: user.id, documentIds })
  revalidatePath(`/workspaces/${workspaceId}/bills`)
  redirect(`/api/workspaces/${workspaceId}/payment-runs/${run.id}/download`)
}

