      </div>
    </Dialog>
  }

  return <Dialog open={open} onClose={close} title="Create payment batch" width="max-w-2xl"
    description="Submits the eligible invoices for an owner's approval. The payment file is downloaded once approved; no money moves.">
    <form className="flex max-h-[75vh] flex-col" onSubmit={(event) => { event.preventDefault(); void submit() }}>
      <div className="min-h-0 flex-1 space-y-4 overflow-y-auto px-5 py-4">
