          <span className="font-medium">Eligible for payment ({eligible.length} of {kept.length})</span>
        </div>

        {groups.length > 1 && <p role="status" className="rounded-md bg-slate-50 px-3 py-2 text-sm text-slate-700 ring-1 ring-slate-200">
