        return result
      }} />
  </>
}

function MarkPaidRecap({ rows, money }: { rows: BillPayRow[]; money: (value: number, currency: string | null) => string }) {
  const scheduled = rows.filter((row) => row.bill.paidState.state === "scheduled")
