  open: boolean
  onClose: () => void
  accounts: PayerAccountRow[]
  count: number
  onSubmit: (accountId: string) => Promise<{ success: boolean; error?: string }>
}) {
  const [accountId, setAccountId] = useState(accounts.find((a) => a.isDefault)?.id ?? accounts[0]?.id ?? "")
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)
  return <Dialog open={open} onClose={() => { if (!busy) onClose() }} title="Set Pay From" description={`The payer account ${count === 1 ? "this invoice" : `these ${count} invoices`} will be paid from. One batch pays from one account.`}>
