      empty={{ title: "No batches yet.", body: "Select invoices in Bill Pay to create one.", filteredBody: "Clear a filter to widen the queue." }}
      loadDetail={(batchId) => getPaymentBatchDetailAction(workspaceId, batchId)}
      paneActions={(batch) => {
        if (batch.view === "pending_approval") {
          if (!isOwner) return <p className="mr-auto text-xs text-slate-600">Waiting for an owner to approve.</p>
          return <>
            <Button type="button" size="sm" variant="outline" disabled={busy} onClick={() => setRejecting(batch)}><XCircle className="h-3.5 w-3.5" aria-hidden />Reject…</Button>
            <Button type="button" size="sm" disabled={busy} onClick={() => setApproving(batch)}><CheckCircle2 className="h-3.5 w-3.5" aria-hidden />Approve</Button>
          </>
        }
        if (batch.view === "approved") {
          return <>
            <Button asChild size="sm" variant="outline"><a href={`/api/workspaces/${workspaceId}/payment-runs/${batch.id}/download`} onClick={() => window.setTimeout(() => router.refresh(), 1500)}><Download className="h-3.5 w-3.5" aria-hidden />{batch.exportedAt ? "Download again" : "Download payment file"}</a></Button>
            {isOwner && <Button type="button" size="sm" disabled={busy} onClick={() => setMarkingPaid(batch)}><CheckCircle2 className="h-3.5 w-3.5" aria-hidden />Mark batch as paid…</Button>}
          </>
        }
        if (batch.view === "paid") return <p className="mr-auto text-xs text-slate-600">Paid {formatPaymentDate(batch.paidAt)}{batch.paidBy ? ` by ${batch.paidBy.name}` : ""}.</p>
        return <p className="mr-auto text-xs text-slate-600">Rejected {formatPaymentDate(batch.rejectedAt)}. Its invoices are back on Bill Pay.</p>
      }} />

    <ConfirmDialog open={approving !== null} busy={busy}
      title={`Approve ${approving?.name ?? "this batch"}?`}
      description={`${approving?.billCount ?? 0} bill${approving?.billCount === 1 ? "" : "s"}, ${approving ? money(approving.total, approving.currencyCode) : ""} from ${approving?.payFromLabel ?? "—"}. Approving makes the payment file available; no money moves until it is uploaded to the bank.`}
      confirmLabel={busy ? "Approving…" : "Approve batch"}
      onConfirm={() => void approve()} onCancel={() => { if (!busy) setApproving(null) }}>
      {approving?.submittedBy && approving.submittedBy.name && <p className="text-xs text-slate-600">Submitted by {approving.submittedBy.name} · {formatPaymentDateTime(approving.createdAt)}</p>}
    </ConfirmDialog>

    <ReasonDialog open={rejecting !== null} onClose={() => setRejecting(null)}
      action={async (formData) => {
        if (!rejecting) return { success: false, error: "No batch selected" }
        const result = await rejectPaymentBatchAction(workspaceId, rejecting.id, formData)
        if (result.success) { toast.success(`${rejecting.name} rejected — its invoices are back on Bill Pay`); router.refresh() }
        return result
      }}
      title={`Reject ${rejecting?.name ?? "this batch"}`}
      description="The batch closes and every invoice in it returns to Bill Pay. The reason is recorded on the batch and the audit trail."
      submitLabel="Reject batch"
      placeholder="Why is this batch being rejected?" />

    <MarkPaidDialog open={markingPaid !== null} onClose={() => setMarkingPaid(null)}
      title={`Mark ${markingPaid?.name ?? "this batch"} as paid`}
      description="Records a payment for every invoice in the batch. The ledger isn't changed; the invoices read “Paid (recorded)” until it confirms."
      submitLabel="Mark batch as paid"
      recap={markingPaid && <p className="rounded-md bg-slate-50 px-3 py-2 text-sm text-slate-700 ring-1 ring-slate-200">{markingPaid.billCount} bill{markingPaid.billCount === 1 ? "" : "s"} · <span className="font-semibold tabular-nums text-slate-900">{money(markingPaid.total, markingPaid.currencyCode)}</span> · Pay From {markingPaid.payFromLabel}{!markingPaid.exportedAt && <span className="mt-1 block text-xs text-amber-800">The payment file hasn't been downloaded yet.</span>}</p>}
      onSubmit={async (input) => {
        if (!markingPaid) return { success: false, error: "No batch selected" }
        const result = await markPaymentBatchPaidAction(workspaceId, markingPaid.id, input)
        if (result.success) { toast.success(`${markingPaid.name} marked paid`); router.refresh() }
        return result
      }} />
    {busy && <span className="sr-only" role="status"><Loader2 className="inline h-3 w-3" aria-hidden />Working…</span>}
  </>
}

