// Autopilot helper: run the #250 Playwright verification from the scratchpad with the seeded ids.
import { spawnSync } from 'node:child_process'
const r = spawnSync('node', ['/tmp/scratch229/po250.mjs', process.argv[2] ?? 'all'], {
  cwd: '/tmp/scratch229',
  env: {
    ...process.env,
    WS: 'af91555d-7450-4b21-a8ac-73db092617c8',
    INV: '10a4d716-56d4-4311-b322-7297262996d3',
    PO: '9ccd3d76-5325-44b7-8a9a-89650a297874',
    SUG: 'f8aae653-d6f2-497d-90a9-7e2d62dc6356',
    ...(process.argv[3] ? { VERBOSE: '1' } : {}),
    ...(process.argv[4] ? { WIDTHS: process.argv[4] } : {}),
  },
  encoding: 'utf8', maxBuffer: 1e8,
})
process.stdout.write((r.stdout || '') + (r.stderr || ''))

// #250 live verification: screenshots + in-page detector for Invoices (pane open, View PO on),
// the breakdown popover, Match manually, and Purchase Orders (list + pane), at 1440 and 390.
// Usage: node po250.mjs <mode> where mode = shots | detect | all ; env WS, INV, PO, SUG
import { chromium } from "playwright"
import fs from "node:fs"

const WS = process.env.WS
const INV = process.env.INV
const PO = process.env.PO
const SUG = process.env.SUG
const base = `http://localhost:3000/workspaces/${WS}`
const mode = process.argv[2] ?? "all"
const outDir = "/tmp/scratch229/shots250"
fs.mkdirSync(outDir, { recursive: true })

const browser = await chromium.launch()
const results = []

async function detect(page, label, width) {
  // Park the pointer off the rail: at (0,0) it hovers the icon rail, which expands over the list.
  await page.mouse.move(width / 2, 60)
  await page.waitForTimeout(300)
  await page.addScriptTag({ url: "http://localhost:8400/detect.js" })
  await page.waitForTimeout(600)
  const findings = await page.evaluate(async () => window.impeccableDetectAsync({}))
  const flat = []
  for (const group of findings) for (const f of group.findings ?? []) flat.push({ type: f.type || f.id, detail: (f.detail || f.snippet || "").slice(0, 160), el: (group.el?.slice?.(0, 120) ?? group.selector ?? "") })
  const byType = {}
  for (const f of flat) byType[f.type] = (byType[f.type] ?? 0) + 1
  results.push({ label, width, count: flat.length, byType })
  if (process.env.VERBOSE) for (const f of flat) console.log(`  [${label}@${width}] ${f.type}: ${f.detail} :: ${f.el}`)
}

async function scenario(width) {
  const page = await browser.newPage({ viewport: { width, height: width < 600 ? 844 : 900 } })
  const errors = []
  page.on("pageerror", (e) => errors.push(String(e.message)))
  await page.mouse.move(width / 2, 60)
  const shot = (name) => page.screenshot({ path: `${outDir}/${name}-${width}.png`, fullPage: false })

  // 1. Invoices list
  await page.goto(`${base}/invoices`, { waitUntil: "networkidle", timeout: 90000 })
  await page.waitForTimeout(500)
  await shot("invoices-list")
  if (mode !== "shots") await detect(page, "invoices-list", width)

  // 2. Pane open on the mismatch invoice (deep link)
  await page.goto(`${base}/invoices/${INV}`, { waitUntil: "networkidle", timeout: 90000 })
  await page.locator("#queue-detail-pane-title").first().waitFor({ timeout: 60000 }).catch((e) => console.log("pane wait:", e.message.split("\n")[0]))
  await page.waitForTimeout(1200)
  // scroll the line items into view inside the pane
  await page.locator("button:has-text(\"Match manually\")").first().waitFor({ timeout: 60000 }).catch((e) => console.log("line items wait:", e.message.split("\n")[0]))
  await page.locator("button:has-text(\"Match manually\")").first().scrollIntoViewIfNeeded().catch(() => {})
  await page.waitForTimeout(300)
  await shot("invoice-pane-viewpo")
  if (mode !== "shots") await detect(page, "invoice-pane-viewpo", width)

  // 3. Breakdown popover on the first ≠ glyph
  const glyph = page.locator('button[aria-label^="Does not match the PO"]').first()
  if (await glyph.count()) {
    await glyph.scrollIntoViewIfNeeded()
    await glyph.click()
    await page.waitForTimeout(400)
    await shot("invoice-pane-breakdown")
    if (mode !== "shots") await detect(page, "invoice-pane-breakdown", width)
    await page.keyboard.press("Escape")
    await page.waitForTimeout(200)
  } else console.log(`[${width}] no ≠ glyph found`)

  // 4. Match manually
  const mm = page.locator('button:has-text("Match manually")').first()
  if (await mm.count()) {
    await mm.scrollIntoViewIfNeeded()
    await mm.click()
    await page.waitForTimeout(500)
    await shot("invoice-pane-match-manually")
    if (mode !== "shots") await detect(page, "invoice-pane-match-manually", width)
  } else console.log(`[${width}] no Match manually button`)

  // 5. Suggested-PO invoice pane
  if (SUG) {
    await page.goto(`${base}/invoices/${SUG}`, { waitUntil: "networkidle", timeout: 90000 })
    await page.locator("#queue-detail-pane-title").first().waitFor({ timeout: 60000 }).catch(() => {})
    await page.waitForTimeout(1000)
    await page.locator("text=Line items").first().scrollIntoViewIfNeeded().catch(() => {})
    await shot("invoice-pane-suggested")
  }

  // 6. Purchase Orders list + pane
  await page.goto(`${base}/purchase-orders`, { waitUntil: "networkidle", timeout: 90000 })
  await page.waitForTimeout(500)
  await shot("po-list")
  if (mode !== "shots") await detect(page, "po-list", width)
  await page.goto(`${base}/purchase-orders/${PO}`, { waitUntil: "networkidle", timeout: 90000 })
  await page.locator("#queue-detail-pane-title").first().waitFor({ timeout: 60000 }).catch(() => {})
  await page.locator("#po-consumption-title").first().waitFor({ timeout: 60000 }).catch((e) => console.log("po pane wait:", e.message.split("\n")[0]))
  await page.waitForTimeout(600)
  await page.locator("#po-consumption-title").first().scrollIntoViewIfNeeded().catch(() => {})
  await shot("po-pane")
  if (mode !== "shots") await detect(page, "po-pane", width)

  if (errors.length) console.log(`[${width}] pageErrors:`, errors.slice(0, 3))
  await page.close()
}

for (const width of (process.env.WIDTHS ?? "1440,390").split(",").map(Number)) await scenario(width)
await browser.close()
for (const r of results) console.log(`${r.label} @${r.width}: ${r.count} findings ${JSON.stringify(r.byType)}`)

