// #251 live verification: screenshots + in-page detector for Bill Pay (list, pane open, Create
// batch dialog) and Payment Batches (list, pane open), at 1440 and 390. `flow` drives the real
// actions once (create a batch from two rows, approve it) so the batches queue has data.
// Usage: node pay251.mjs <mode> where mode = flow | shots | detect | all ; env WS
import { chromium } from "playwright"
import fs from "node:fs"

const WS = process.env.WS
const base = `http://localhost:3000/workspaces/${WS}`
const mode = process.argv[2] ?? "all"
const outDir = "/tmp/scratch229/shots251"
fs.mkdirSync(outDir, { recursive: true })

const browser = await chromium.launch()
const results = []

async function detect(page, label, width) {
  await page.mouse.move(width / 2, 60)
  await page.waitForTimeout(300)
  await page.addScriptTag({ url: "http://localhost:8400/detect.js" })
  await page.waitForTimeout(600)
  const findings = await page.evaluate(async () => window.impeccableDetectAsync({}))
  const flat = []
  for (const group of findings) for (const f of group.findings ?? []) flat.push({ type: f.type || f.id, detail: (f.detail || f.snippet || "").slice(0, 160), el: (group.el?.slice?.(0, 140) ?? group.selector ?? "") })
  const byType = {}
  for (const f of flat) byType[f.type] = (byType[f.type] ?? 0) + 1
  results.push({ label, width, count: flat.length, byType })
  if (process.env.VERBOSE) for (const f of flat) console.log(`  [${label}@${width}] ${f.type}: ${f.detail} :: ${f.el}`)
}

async function flow() {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
  const errors = []
  page.on("pageerror", (e) => errors.push(String(e.message)))
  await page.goto(`${base}/payments/bill-pay`, { waitUntil: "networkidle", timeout: 90000 })
  await page.mouse.move(720, 60)
  // select the two Bergrivier rows (eligible, ZAR)
  const boxes = page.locator('input[type=checkbox][aria-label^="Select Bergrivier"]')
  const n = await boxes.count()
  console.log("bergrivier rows:", n)
  for (let i = 0; i < n; i++) await boxes.nth(i).check()
  await page.locator('button:has-text("Create batch")').first().click()
  await page.locator('[role=dialog]').waitFor({ timeout: 20000 })
  await page.waitForTimeout(400)
  await page.screenshot({ path: `${outDir}/create-batch-dialog-flow-1440.png` })
  await page.locator('[role=dialog] button[type=submit]').click()
  await page.locator('[role=dialog]:has-text("submitted")').waitFor({ timeout: 30000 }).catch((e) => console.log("receipt wait:", e.message.split("\n")[0]))
  await page.waitForTimeout(400)
  await page.screenshot({ path: `${outDir}/create-batch-receipt-1440.png` })
  const link = page.locator('[role=dialog] a[href*="/payments/batches/"]').first()
  const href = await link.getAttribute("href").catch(() => null)
  console.log("batch href:", href)
  await page.locator('[role=dialog] button:has-text("Done")').click()
  await page.waitForTimeout(500)
  if (href) {
    await page.goto(`http://localhost:3000${href}`, { waitUntil: "networkidle", timeout: 90000 })
    await page.locator("#queue-detail-pane-title").first().waitFor({ timeout: 60000 })
    await page.waitForTimeout(800)
    await page.screenshot({ path: `${outDir}/batch-pane-pending-1440.png` })
    // approve it so an Approved batch exists too
    await page.locator('button:has-text("Approve")').last().click()
    await page.locator('[role=alertdialog], [role=dialog]').first().waitFor({ timeout: 20000 })
    await page.waitForTimeout(300)
    await page.screenshot({ path: `${outDir}/batch-approve-confirm-1440.png` })
    await page.locator('[role=alertdialog] button:has-text("Approve batch"), [role=dialog] button:has-text("Approve batch")').first().click()
    await page.waitForTimeout(2500)
    await page.screenshot({ path: `${outDir}/batch-pane-approved-1440.png` })
  }
  // second batch: Cape Office (discount) — stays pending
  await page.goto(`${base}/payments/bill-pay`, { waitUntil: "networkidle", timeout: 90000 })
  const cape = page.locator('input[type=checkbox][aria-label^="Select Cape Office"]')
  const c = await cape.count()
  for (let i = 0; i < c; i++) await cape.nth(i).check()
  if (c > 0) {
    await page.locator('button:has-text("Create batch")').first().click()
    await page.locator('[role=dialog]').waitFor({ timeout: 20000 })
    await page.locator('[role=dialog] button[type=submit]').click()
    await page.locator('[role=dialog]:has-text("submitted")').waitFor({ timeout: 30000 }).catch(() => {})
    await page.locator('[role=dialog] button:has-text("Done")').click().catch(() => {})
  }
  if (errors.length) console.log("flow pageErrors:", errors.slice(0, 3))
  await page.close()
}

async function scenario(width) {
  const page = await browser.newPage({ viewport: { width, height: width < 600 ? 844 : 900 } })
  const errors = []
