content.content:
1	"use client"
2	
3	import { useState } from "react"
4	import { useRouter } from "next/navigation"
5	import { toast } from "sonner"
6	import { CheckCircle2, Download, Loader2, XCircle } from "lucide-react"
7	import { Button } from "@/components/ui/button"
8	import { ConfirmDialog } from "@/components/ui/confirm-dialog"
9	import { QueueScreen, type QueueColumn, type SortOption } from "@/components/queue/queue-screen"
10	import type { Facet } from "@/components/queue/facet-filters"
11	import { TitleCell } from "@/components/queue/row-cells"
12	import { ReasonDialog } from "@/components/list-screen/reason-dialog-button"
13	import { MarkPaidDialog } from "@/components/payments/mark-paid-dialog"
14	import { formatPaymentDate, formatPaymentDateTime, formatPaymentMoney } from "@/components/payments/format"
15	import { resolveCountdown } from "@/lib/documents/countdown"
16	import { BATCH_VIEW_LABEL } from "@/lib/payments/batch-status"
17	import { approvePaymentBatchAction, getPaymentBatchDetailAction, markPaymentBatchPaidAction, rejectPaymentBatchAction } from "@/app/(app)/workspaces/[workspaceId]/(queue)/payments/actions"
18	import type { PaymentBatchRow } from "@/models/payment-batches"
19	
20	/** #229 Q11 (#251): the Payment Batches queue — system views Pending approval · Approved ·
21	 * Paid, Rejected under Closed; the 60% Detail pane with a sticky Reject · Approve while
22	 * pending, Download payment file · Mark batch as paid once approved. Server-confirmed writes,
23	 * no optimistic removal, no Undo, no single-key approve (#227's rules). */
24	export const BATCH_FACETS: Facet[] = [
25	  {
26	    param: "view", label: "Status",
27	    sections: [
28	      { label: "Open", options: [{ value: "pending_approval", label: "Pending approval" }, { value: "approved", label: "Approved" }] },
29	      { label: "Closed", options: [{ value: "paid", label: "Paid" }, { value: "rejected", label: "Rejected" }] },
30	    ],
31	  },
32	]
33	
34	const SORTS: SortOption<PaymentBatchRow>[] = [
35	  { key: "newest", label: "Newest first", compare: (a, b) => b.createdAt.getTime() - a.createdAt.getTime() },
36	  { key: "due", label: "Due date", compare: (a, b) => (a.earliestDue?.getTime() ?? Infinity) - (b.earliestDue?.getTime() ?? Infinity) },
37	  { key: "amount", label: "Total, high to low", compare: (a, b) => b.total - a.total },
38	]
39	
40	const PILL: Record<PaymentBatchRow["view"], string> = {
41	  pending_approval: "bg-blue-100 text-blue-800",
42	  approved: "bg-emerald-100 text-emerald-800",
43	  paid: "bg-slate-200 text-slate-800",
44	  rejected: "bg-amber-100 text-amber-900",
45	}
46	
47	export function PaymentBatchQueue({ workspaceId, basePath, rows, fallbackCurrency, isOwner, stat, initialSelectedId }: {
48	  workspaceId: string
49	  basePath: string
50	  rows: PaymentBatchRow[]
51	  fallbackCurrency: string
52	  isOwner: boolean
53	  stat?: React.ReactNode
54	  initialSelectedId?: string | null
55	}) {
56	  const router = useRouter()
57	  const [approving, setApproving] = useState<PaymentBatchRow | null>(null)
58	  const [rejecting, setRejecting] = useState<PaymentBatchRow | null>(null)
59	  const [markingPaid, setMarkingPaid] = useState<PaymentBatchRow | null>(null)
60	  const [busy, setBusy] = useState(false)
61	  const money = (value: number, currency: string | null) => formatPaymentMoney(value, currency, fallbackCurrency)
62	
63	  const columns: QueueColumn<PaymentBatchRow>[] = [
64	    { key: "name", label: "Batch name", narrow: true, className: "min-w-[11rem]", render: (batch) => <TitleCell title={batch.name} subtitle={batch.comment} /> },
65	    { key: "status", label: "Status", narrow: true, className: "whitespace-nowrap", render: (batch) => <span className={`inline-flex items-center whitespace-nowrap rounded-full px-2 py-0.5 text-xs font-medium ${PILL[batch.view]}`}>{BATCH_VIEW_LABEL[batch.view]}</span> },
66	    { key: "created", label: "Created", className: "whitespace-nowrap tabular-nums text-slate-700", render: (batch) => formatPaymentDateTime(batch.createdAt) },
67	    { key: "submittedBy", label: "Submitted by", className: "whitespace-nowrap text-slate-700", render: (batch) => batch.submittedBy?.name ?? "—" },
68	    {
69	      key: "due", label: "Due", narrow: true, className: "whitespace-nowrap tabular-nums text-slate-700",
70	      render: (batch) => {
71	        const countdown = batch.view === "pending_approval" || batch.view === "approved" ? resolveCountdown(batch.earliestDue, new Date(), 3) : null
72	        return <span className="inline-flex flex-wrap items-center gap-1.5">
73	          <span>{formatPaymentDate(batch.earliestDue)}</span>
74	          {countdown && countdown.urgency === "overdue" && <span className="rounded-full bg-red-50 px-2 py-0.5 text-xs font-semibold text-red-800">{countdown.label}</span>}
75	          {countdown && countdown.urgency === "expiring" && <span className="rounded-full bg-purple-50 px-2 py-0.5 text-xs font-semibold text-purple-700">{countdown.label.replace("Expires", "Due")}</span>}
76	        </span>
77	      },
78	    },
79	    { key: "bills", label: "Bills", className: "whitespace-nowrap text-right tabular-nums text-slate-700", render: (batch) => batch.billCount },
80	    { key: "total", label: "Total", narrow: true, className: "whitespace-nowrap text-right tabular-nums text-slate-900", render: (batch) => money(batch.total, batch.currencyCode) },
81	    { key: "currency", label: "Currency", className: "whitespace-nowrap text-slate-700", render: (batch) => batch.currencyCode },
82	    { key: "payFrom", label: "Pay From", className: "whitespace-nowrap text-slate-700", render: (batch) => batch.payFromLabel },
83	  ]
84	
85	  const approve = async () => {
86	    if (!approving) return
87	    setBusy(true)
88	    try {
89	      const result = await approvePaymentBatchAction(workspaceId, approving.id)
90	      if (!result.success) { toast.error(result.error ?? "Couldn't approve this batch"); return }
91	      toast.success(`${approving.name} approved — the payment file is ready to download`)
92	      setApproving(null)
93	      router.refresh()
94	    } catch { toast.error("Couldn't reach the server. Nothing changed — try again.") } finally { setBusy(false) }
95	  }
96	
97	  return <>
98	    <QueueScreen<PaymentBatchRow>
99	      title="Payment Batches"
100	      basePath={basePath}
101	      rows={rows}
102	      rowId={(batch) => batch.id}
103	      rowTitle={(batch) => batch.name}
104	      rowSubtitle={(batch) => `${BATCH_VIEW_LABEL[batch.view]} · ${batch.billCount} bill${batch.billCount === 1 ? "" : "s"} · ${money(batch.total, batch.currencyCode)}`}
105	      columns={columns}
106	      sortOptions={SORTS}
107	      facets={BATCH_FACETS}
108	      sortParam="sort"
109	      stat={stat}
110	      initialSelectedId={initialSelectedId}
111	      empty={{ title: "No batches yet.", body: "Select invoices in Bill Pay to create one.", filteredBody: "Clear a filter to widen the queue." }}
112	      loadDetail={(batchId) => getPaymentBatchDetailAction(workspaceId, batchId)}
113	      paneActions={(batch) => {
114	        if (batch.view === "pending_approval") {
115	          if (!isOwner) return <p className="mr-auto text-xs text-slate-600">Waiting for an owner to approve.</p>
116	          return <>
117	            <Button type="button" size="sm" variant="outline" disabled={busy} onClick={() => setRejecting(batch)}><XCircle className="h-3.5 w-3.5" aria-hidden />Reject…</Button>
118	            <Button type="button" size="sm" disabled={busy} onClick={() => setApproving(batch)}><CheckCircle2 className="h-3.5 w-3.5" aria-hidden />Approve</Button>
119	          </>
120	        }
121	        if (batch.view === "approved") {
122	          return <>
123	            <Button asChild size="sm" variant="outline"><a className="py-1.5" href={`/api/workspaces/${workspaceId}/payment-runs/${batch.id}/download`} onClick={() => window.setTimeout(() => router.refresh(), 1500)}><Download className="h-3.5 w-3.5" aria-hidden />{batch.exportedAt ? "Download again" : "Download payment file"}</a></Button>
124	            {isOwner && <Button type="button" size="sm" disabled={busy} onClick={() => setMarkingPaid(batch)}><CheckCircle2 className="h-3.5 w-3.5" aria-hidden />Mark batch as paid…</Button>}
125	          </>
126	        }
127	        if (batch.view === "paid") return <p className="mr-auto text-xs text-slate-600">Paid {formatPaymentDate(batch.paidAt)}{batch.paidBy ? ` by ${batch.paidBy.name}` : ""}.</p>
128	        return <p className="mr-auto text-xs text-slate-600">Rejected {formatPaymentDate(batch.rejectedAt)}. Its invoices are back on Bill Pay.</p>
129	      }} />
130	
131	    <ConfirmDialog open={approving !== null} busy={busy}
132	      title={`Approve ${approving?.name ?? "this batch"}?`}
133	      description={`${approving?.billCount ?? 0} bill${approving?.billCount === 1 ? "" : "s"}, ${approving ? money(approving.total, approving.currencyCode) : ""} from ${approving?.payFromLabel ?? "—"}. Approving makes the payment file available; no money moves until it is uploaded to the bank.`}
134	      confirmLabel={busy ? "Approving…" : "Approve batch"}
135	      onConfirm={() => void approve()} onCancel={() => { if (!busy) setApproving(null) }}>
136	      {approving?.submittedBy && approving.submittedBy.name && <p className="text-xs text-slate-600">Submitted by {approving.submittedBy.name} · {formatPaymentDateTime(approving.createdAt)}</p>}
137	    </ConfirmDialog>
138	
139	    <ReasonDialog open={rejecting !== null} onClose={() => setRejecting(null)}
140	      action={async (formData) => {
141	        if (!rejecting) return { success: false, error: "No batch selected" }
142	        const result = await rejectPaymentBatchAction(workspaceId, rejecting.id, formData)
143	        if (result.success) { toast.success(`${rejecting.name} rejected — its invoices are back on Bill Pay`); router.refresh() }
144	        return result
145	      }}
146	      title={`Reject ${rejecting?.name ?? "this batch"}`}
147	      description="The batch closes and every invoice in it returns to Bill Pay. The reason is recorded on the batch and the audit trail."
148	      submitLabel="Reject batch"
