1	/** ADR 0001 / #229 Q6 (#251): an invoice's paid state is **derived, ledger first, then payment
2	 * records**. The ledger's confirmation wins when it exists; otherwise DocuBite's own Payment
3	 * records against the amount due decide Paid / Partially paid / Unpaid, and membership of a
4	 * pending or approved Payment batch reads as Scheduled. The `source` says which authority the
5	 * state was read from, so the pill can say "Paid (recorded)" when the ledger has not confirmed.
6	 * Money maths in cents. */
7	
8	export type PaidState = "paid" | "partially_paid" | "scheduled" | "unpaid"
9	export type PaidSource = "ledger" | "recorded" | null
10	
11	export type DerivedPaidState = {
12	  state: PaidState
13	  source: PaidSource
14	  /** Whole-cent amount recorded or confirmed paid; 0 when unpaid. */
15	  paidAmount: number
16	  /** The pill's words — one vocabulary on every surface. */
17	  label: string
18	}
19	
20	export type PaidStateInput = {
21	  /** The ledger's own status for this document, when it has one (`models/ledger-payments.ts`). */
22	  ledgerStatus: string | null
23	  ledgerPaidAmount: number | null
24	  /** The bill total; null when the document has none (then only the ledger can call it paid). */
25	  total: number | null
26	  /** Live (not removed) payment records against the invoice. */
27	  records: Array<{ amount: number }>
28	  /** The status of the newest live batch holding this invoice, when there is one. */
29	  batchStatus: "pending_approval" | "approved" | "paid" | "rejected" | "draft" | "sent" | null
30	}
31	
32	const LEDGER_PAID = new Set(["paid", "reconciled"])
33	const LEDGER_PARTIAL = new Set(["partially_paid", "partial"])
34	
35	export function derivePaidState(input: PaidStateInput): DerivedPaidState {
36	  const ledger = input.ledgerStatus?.toLowerCase() ?? null
37	  if (ledger && LEDGER_PAID.has(ledger)) {
38	    return { state: "paid", source: "ledger", paidAmount: input.ledgerPaidAmount ?? input.total ?? 0, label: "Paid" }
39	  }
40	  if (ledger && LEDGER_PARTIAL.has(ledger)) {
41	    return { state: "partially_paid", source: "ledger", paidAmount: input.ledgerPaidAmount ?? 0, label: "Partially paid" }
42	  }
43	
44	  const recordedCents = input.records.reduce((sum, record) => sum + Math.round(record.amount * 100), 0)
45	  const dueCents = input.total !== null ? Math.round(input.total * 100) : null
46	  if (recordedCents > 0 && dueCents !== null && recordedCents >= dueCents) {
47	    return { state: "paid", source: "recorded", paidAmount: recordedCents / 100, label: "Paid (recorded)" }
48	  }
49	  if (recordedCents > 0) {
50	    return { state: "partially_paid", source: "recorded", paidAmount: recordedCents / 100, label: "Partially paid" }
51	  }
52	  if (input.batchStatus === "pending_approval" || input.batchStatus === "approved" || input.batchStatus === "draft" || input.batchStatus === "sent") {
53	    return { state: "scheduled", source: null, paidAmount: 0, label: "Scheduled" }
54	  }
55	  return { state: "unpaid", source: null, paidAmount: 0, label: "Unpaid" }
56	}
57	
58	/** The remaining amount a partially paid invoice still owes, in whole cents → number. */
59	export function remainingDue(total: number | null, paidAmount: number): number | null {
60	  if (total === null) return null
61	  return Math.max(0, Math.round(total * 100) - Math.round(paidAmount * 100)) / 100
62	}
