18	const MESSAGES: Record<string, string> = {
19	  owner_only: "Only a workspace owner can decide a payment batch.",
20	  payment_batch_not_found: "That batch no longer exists.",
21	  payment_batch_not_pending: "This batch has already been decided.",
22	  payment_batch_not_approved: "This batch isn't approved yet, so it can't be marked paid.",
23	  reason_required: "A reason is required.",
