25	  payment_record_not_found: "That payment record no longer exists.",
26	  document_not_found: "That invoice no longer exists.",
27	}
28	const message = (error: unknown, fallback: string) => (error instanceof Error && MESSAGES[error.message]) || errorMessage(error, fallback)
