38	  revalidatePath(p.billPay); revalidatePath(p.batches); revalidatePath(p.invoices)
39	  // The rail badge (batches pending approval) lives on the layout.
40	  revalidatePath("/workspaces/[workspaceId]", "layout")
41	}
