43	export async function setAmountToPayAction(workspaceId: string, documentId: string, amount: number | null, due: number): Promise<ActionState<null>> {
44	  const user = await getCurrentUser()
45	  if (!(await requireMember(workspaceId, user.id))) return { success: false, error: NO_ACCESS }
46	  if (amount !== null) { const problem = validateAmountToPay(amount, due); if (problem) return { success: false, error: problem } }
47	  try {
48	    await saveBillPayPreference({ workspaceId, actorId: user.id, documentId, amountToPay: amount })
49	  } catch (error) { return { success: false, error: message(error, "Couldn't save the amount") } }
50	  revalidatePath(paths(workspaceId).billPay)
51	  return { success: true, data: null }
52	}
