54	export async function setPayFromAction(workspaceId: string, documentIds: string[], payFromAccountId: string): Promise<ActionState<{ updated: number }>> {
55	  const user = await getCurrentUser()
56	  if (!(await requireMember(workspaceId, user.id))) return { success: false, error: NO_ACCESS }
57	  if (documentIds.length === 0) return { success: false, error: "Select at least one invoice." }
58	  try {
59	    for (const documentId of documentIds) await saveBillPayPreference({ workspaceId, actorId: user.id, documentId, payFromAccountId })
