1	import type { PaidState } from "@/lib/payments/paid-state"
2	
3	/** #229 Q7 (#251): who belongs on Bill Pay and which of those rows can go into a batch. A row
4	 * is *on* Bill Pay when its processing state is Approved, it is not cancelled and not fully
5	 * paid (the #239 gate). A row is *batchable* only when it also has a supplier bank account and
6	 * is not already in a live batch — the un-batchable rows stay visible with the reason, never
7	 * dropped silently the way `preparePaymentRun` did. Pure; the queue and the server share it. */
8	
9	export type BillPayMembershipInput = {
10	  processingState: "cancelled" | "needs_attention" | "in_review" | "touchless" | "approved"
11	  paidState: PaidState
12	}
13	
14	export function isOnBillPay(input: BillPayMembershipInput): boolean {
15	  if (input.processingState === "cancelled") return false
16	  if (input.processingState !== "approved" && input.processingState !== "touchless") return false
17	  return input.paidState !== "paid"
18	}
19	
20	export type BatchEligibilityReason = "needs_bank_details" | "scheduled" | "no_amount" | "no_supplier"
21	
22	export type BatchEligibility = { eligible: true } | { eligible: false; reason: BatchEligibilityReason }
23	
24	export function batchEligibility(input: { hasBankAccount: boolean; paidState: PaidState; amountToPay: number | null; hasSupplier: boolean }): BatchEligibility {
25	  if (!input.hasSupplier) return { eligible: false, reason: "no_supplier" }
26	  if (input.amountToPay === null || input.amountToPay <= 0) return { eligible: false, reason: "no_amount" }
27	  if (input.paidState === "scheduled") return { eligible: false, reason: "scheduled" }
28	  if (!input.hasBankAccount) return { eligible: false, reason: "needs_bank_details" }
29	  return { eligible: true }
30	}
31	
32	export const ELIGIBILITY_COPY: Record<BatchEligibilityReason, string> = {
33	  needs_bank_details: "Needs bank details",
34	  scheduled: "Already in a batch",
35	  no_amount: "No amount to pay",
36	  no_supplier: "Supplier not on file",
37	}
