// #251: Settings › Payments and the Invoices queue (Paid (recorded) pill) at 1440 + 390, with the detector.
import { chromium } from "playwright"
const WS = process.env.WS
const base = `http://localhost:3000/workspaces/${WS}`
const outDir = "/tmp/scratch229/shots251"
const browser = await chromium.launch()
const results = []
async function detect(page, label, width) {
  await page.mouse.move(width / 2, 60); await page.waitForTimeout(300)
  await page.addScriptTag({ url: "http://localhost:8400/detect.js" }); await page.waitForTimeout(600)
  const findings = await page.evaluate(async () => window.impeccableDetectAsync({}))
  const flat = []
  for (const group of findings) for (const f of group.findings ?? []) flat.push({ type: f.type || f.id, detail: (f.detail || "").slice(0, 160), el: (group.el?.slice?.(0, 140) ?? "") })
  const byType = {}; for (const f of flat) byType[f.type] = (byType[f.type] ?? 0) + 1
  results.push({ label, width, count: flat.length, byType })
  if (process.env.VERBOSE) for (const f of flat) console.log(`  [${label}@${width}] ${f.type}: ${f.detail} :: ${f.el}`)
}
for (const width of [1440, 390]) {
  const page = await browser.newPage({ viewport: { width, height: width < 600 ? 844 : 900 } })
  const errors = []; page.on("pageerror", (e) => errors.push(String(e.message)))
  await page.goto(`${base}/settings/payments`, { waitUntil: "networkidle", timeout: 90000 })
  await page.mouse.move(width / 2, 60); await page.waitForTimeout(500)
  await page.screenshot({ path: `${outDir}/settings-payments-${width}.png`, fullPage: true })
  await detect(page, "settings-payments", width)
  if (width >= 600) {
    await page.locator('button:has-text("Edit")').first().click(); await page.waitForTimeout(300)
    await page.screenshot({ path: `${outDir}/settings-payments-edit-${width}.png`, fullPage: true })
    await detect(page, "settings-payments-edit", width)
  }
  await page.goto(`${base}/invoices`, { waitUntil: "networkidle", timeout: 90000 })
  await page.mouse.move(width / 2, 60); await page.waitForTimeout(500)
  await page.screenshot({ path: `${outDir}/invoices-list-${width}.png` })
  await detect(page, "invoices-list", width)
  if (errors.length) console.log(`[${width}] pageErrors:`, errors.slice(0, 3))
  await page.close()
}
await browser.close()
for (const r of results) console.log(`${r.label} @${r.width}: ${r.count} findings ${JSON.stringify(r.byType)}`)

