1	/** #251: money and dates on the Payments destination. Whole cents (a discount is a cents
2	 * difference), and the workspace's base currency as the fallback — never USD on a ZA file (the
3	 * incumbent's `formatMoney` fell back to "$", a P1 on its critique). */
4	export function formatPaymentMoney(amount: number, currency: string | null | undefined, fallbackCurrency: string): string {
5	  const code = currency && /^[A-Z]{3}$/i.test(currency) ? currency.toUpperCase() : fallbackCurrency.toUpperCase()
6	  try {
7	    return new Intl.NumberFormat("en-ZA", { style: "currency", currency: code, currencyDisplay: "narrowSymbol", minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(amount)
8	  } catch {
9	    return `${code} ${amount.toFixed(2)}`
10	  }
11	}
