41	/** `0 < amount ≤ due`, in cents so 0.1 + 0.2 never bites. Returns the reason it is not, or null. */
42	export function validateAmountToPay(amount: number, due: number): string | null {
43	  if (!Number.isFinite(amount)) return "Enter an amount."
44	  const cents = Math.round(amount * 100)
45	  if (cents <= 0) return "The amount must be more than zero."
46	  if (cents > Math.round(due * 100)) return "The amount can't be more than what's due."
47	  return null
48	}
