44	export async function setAmountToPayAction(workspaceId: string, documentId: string, amount: number | null, due: number): Promise<ActionState<null>> {
45	  const user = await getCurrentUser()
46	  if (!(await requireMember(workspaceId, user.id))) return { success: false, error: NO_ACCESS }
47	  if (amount !== null) { const problem = validateAmountToPay(amount, due); if (problem) return { success: false, error: problem } }
48	  try {
49	    await saveBillPayPreference({ workspaceId, actorId: user.id, documentId, amountToPay: amount })
50	  } catch (error) { return { success: false, error: message(error, "Couldn't save the amount") } }
51	  revalidatePath(paths(workspaceId).billPay)
52	  return { success: true, data: null }
53	}
